import { Store } from 'effector';
import Scope from './models/Scope';
interface PermissionService {
    getScopes(): Array<string>;
    hasOneOfScopes(scopes: Array<string> | string): boolean;
    hasScopes(scopesFromStore: Array<string>, userScope: Array<string> | string): boolean;
    has(userScope: Array<string> | string): boolean;
    hasScopesToApp(appName: string): boolean;
    addScopes(scopes: Array<string>): void;
    getStore(): Store<Scope>;
    getScopesFromJwt(): Array<string>;
}
export default PermissionService;
